package com.fooddelivery.delivery.entity;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="deliveries") public class Delivery {
 @Id @Column(name="order_id") private Long orderId;@Column(name="user_id",nullable=false)private Long userId;@Column(name="customer_email",length=320)private String customerEmail;@Column(name="customer_phone",length=30)private String customerPhone;@Column(name="sms_opt_in",nullable=false)private boolean smsOptIn;@Column(name="delivery_address",nullable=false,length=500)private String deliveryAddress;@Column(name="total_amount",nullable=false,precision=12,scale=2)private BigDecimal totalAmount;@Column(nullable=false,length=30)private String status="READY";@Column(name="driver_id")private Long driverId;private BigDecimal latitude;private BigDecimal longitude;@Column(name="delivery_latitude",precision=10,scale=7)private BigDecimal deliveryLatitude;@Column(name="delivery_longitude",precision=10,scale=7)private BigDecimal deliveryLongitude;@Column(name="updated_at",insertable=false,updatable=false)private LocalDateTime updatedAt;
 protected Delivery(){}public Delivery(Long orderId,Long userId,String email,String phone,boolean smsOptIn,String address,BigDecimal amount,BigDecimal deliveryLatitude,BigDecimal deliveryLongitude){this.orderId=orderId;this.userId=userId;customerEmail=email;customerPhone=phone;this.smsOptIn=smsOptIn;deliveryAddress=address;totalAmount=amount;this.deliveryLatitude=deliveryLatitude;this.deliveryLongitude=deliveryLongitude;}
 public Long getOrderId(){return orderId;}public Long getUserId(){return userId;}public String getCustomerEmail(){return customerEmail;}public String getCustomerPhone(){return customerPhone;}public boolean isSmsOptIn(){return smsOptIn;}public String getDeliveryAddress(){return deliveryAddress;}public BigDecimal getTotalAmount(){return totalAmount;}public String getStatus(){return status;}public Long getDriverId(){return driverId;}public BigDecimal getLatitude(){return latitude;}public BigDecimal getLongitude(){return longitude;}public BigDecimal getDeliveryLatitude(){return deliveryLatitude;}public BigDecimal getDeliveryLongitude(){return deliveryLongitude;}public LocalDateTime getUpdatedAt(){return updatedAt;}public void assignDriver(Long id){driverId=id;}public void setStatus(String status){this.status=status;}public void setLocation(BigDecimal lat,BigDecimal lon){latitude=lat;longitude=lon;}
}
